import { FastifyInstance } from 'fastify';
import { Pool } from 'pg';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export async function registerGeography(app: FastifyInstance, pool: Pool, ready: boolean): Promise<void> {
  app.get('/api/catalog/geography', async (req, reply) => {
    const rid = req.id;
    const err = (code: number, c: string, m: string) => reply.code(code).send({ error: { code: c, message: m }, request_id: rid });

    if (!ready) return err(503, 'catalog_unavailable', 'Catalogue unavailable');

    const q = req.query as Record<string, unknown>;
    const keys = Object.keys(q);
    const allowed = ['country_id', 'province_id'];
    if (keys.some(k => !allowed.includes(k))) return err(400, 'invalid_request', 'Invalid request');

    const rawCid = q.country_id;
    const rawPid = q.province_id;

    let cid: string | null = null;
    let pid: string | null = null;

    if (rawCid !== undefined) {
      if (typeof rawCid !== 'string' || !UUID_RE.test(rawCid)) return err(400, 'invalid_request', 'Invalid request');
      cid = rawCid.toLowerCase();
    }
    if (rawPid !== undefined) {
      if (typeof rawPid !== 'string' || !UUID_RE.test(rawPid)) return err(400, 'invalid_request', 'Invalid request');
      pid = rawPid.toLowerCase();
    }

    try {
      const cRes = await pool.query('SELECT id, code, name FROM agentapp.countries WHERE code = $1', ['AR']);
      if (cRes.rows.length === 0) return err(503, 'catalog_unavailable', 'Catalogue unavailable');

      const allCountries = cRes.rows;
      let countries = allCountries;
      let provinces: any[] = [];
      let zones: any[] = [];

      if (cid && pid) {
        const c = allCountries.find(r => r.id.toLowerCase() === cid);
        if (!c) return err(422, 'geography_invalid', 'Invalid geography');

        const pRes = await pool.query('SELECT id, country_id, name FROM agentapp.provinces WHERE id = $1 AND country_id = $2', [pid, c.id]);
        if (pRes.rows.length === 0) return err(422, 'geography_invalid', 'Invalid geography');

        const p = pRes.rows[0];
        countries = [c];
        provinces = [p];

        const zRes = await pool.query('SELECT id, country_id, province_id, name FROM agentapp.zones WHERE province_id = $1 AND country_id = $2', [pid, c.id]);
        zones = zRes.rows;
      } else if (cid) {
        const c = allCountries.find(r => r.id.toLowerCase() === cid);
        if (!c) return err(422, 'geography_invalid', 'Invalid geography');

        countries = [c];
        const pRes = await pool.query('SELECT id, country_id, name FROM agentapp.provinces WHERE country_id = $1', [c.id]);
        provinces = pRes.rows;
        if (provinces.length === 0) return err(503, 'catalog_unavailable', 'Catalogue unavailable');

        const zRes = await pool.query('SELECT id, country_id, province_id, name FROM agentapp.zones WHERE country_id = $1', [c.id]);
        zones = zRes.rows;
      } else if (pid) {
        const pRes = await pool.query('SELECT id, country_id, name FROM agentapp.provinces WHERE id = $1', [pid]);
        if (pRes.rows.length === 0) return err(422, 'geography_invalid', 'Invalid geography');

        const p = pRes.rows[0];
        const c = allCountries.find(r => r.id.toLowerCase() === p.country_id);
        if (!c) return err(422, 'geography_invalid', 'Invalid geography');

        countries = [c];
        provinces = [p];

        const zRes = await pool.query('SELECT id, country_id, province_id, name FROM agentapp.zones WHERE province_id = $1 AND country_id = $2', [pid, c.id]);
        zones = zRes.rows;
      } else {
        const c = allCountries[0];
        countries = [c];
        const pRes = await pool.query('SELECT id, country_id, name FROM agentapp.provinces WHERE country_id = $1', [c.id]);
        provinces = pRes.rows;
        if (provinces.length === 0) return err(503, 'catalog_unavailable', 'Catalogue unavailable');

        const zRes = await pool.query('SELECT id, country_id, province_id, name FROM agentapp.zones WHERE country_id = $1', [c.id]);
        zones = zRes.rows;
      }

      return { countries, provinces, zones };
    } catch (e) {
      return err(503, 'service_unavailable', 'Service unavailable');
    }
  });
}

